Lemma bytes_at_tail : forall m P b l, bytes_at bsegs m P (b :: l) -> bytes_at bsegs m (P + 1) l.
Proof. intros m P b l H. change (b :: l) with ([b] ++ l) in H. apply bytes_at_app in H. destruct H as [_ H]. exact H. Qed.

(* [comment removed for export] *)
Lemma vlit_facts : forall m A L, In (A, L) VLITS -> mem_inv bsegs m -> ACONST m ->
  bytes_at bsegs m A (litb L) /\ zbytes (litb L) = L
  /\ accessible m A (Z.of_nat (length L)) /\ shvis m A (A + Z.of_nat (length L))
  /\ in_app_mem A (A + Z.of_nat (length L))
  /\ 0x26b80 <= A /\ A + Z.of_nat (length L) <= 0x26f40.
Proof.
  intros m A L IN MI AC. pose proof VLITS_ok as F. rewrite forallb_forall in F. specialize (F _ IN).
  unfold vlit_okb in F. cbn [fst snd] in F.
  apply andb_prop in F as [F F5]. apply andb_prop in F as [F F4]. apply andb_prop in F as [F F3]. apply andb_prop in F as [F1 F2].
  apply Z.leb_le in F3. apply Z.leb_le in F4.
  destruct (list_eq_dec Z.eq_dec (zbytes (litb L)) L) as [E|NE]; [| discriminate]. clear F5.
  split.
  { pose proof (ro_cells_bytes_at bsegs m A [CB (length (litb L)) (litb L)]) as B.
    cbn [cells_bytes cbytes] in B. rewrite app_nil_r in B. apply B.
    apply (ro_cells_image bsegs m); [exact MI | exact F1 | lia | rewrite length_litb; lia]. }
  split; [exact E|].
  split; [exact (ACONST_gbody_accessible m A _ AC F2)|].
  split; [apply ACONST_img_shvis; [exact AC | unfold AIMG_LO; lia | lia | unfold AIMG_TOP; lia]|].
  split; [apply img_in_app_mem; [unfold AIMG_LO; lia | unfold AIMG_TOP; lia]|].
  split; assumption.
Qed.

