Lemma bcmp_icpt_specZ : bcmp_icpt_stmt ->
  forall ra gp tp t0 t1 t2 s0 s1 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6
    (F : bvmap 5 word) fc (m : mem) (SP L R : Z) (ls rs : list byte) (lo : Z),
  bytes_at bsegs m L ls -> bytes_at bsegs m R rs -> length rs = length ls -> Z.of_nat (length ls) <= 2^40 ->
  accessible m L (Z.of_nat (length ls)) -> accessible m R (Z.of_nat (length ls)) ->
  shvis m L (L + Z.of_nat (length ls)) -> shvis m R (R + Z.of_nat (length ls)) ->
  in_app_mem L (L + Z.of_nat (length ls)) -> in_app_mem R (R + Z.of_nat (length ls)) ->
  stk bsegs m lo SP -> aceil <= lo -> lo <= SP - 4560 -> SP < 2^64 ->
  (L + Z.of_nat (length ls) <= lo \/ SP <= L) -> (R + Z.of_nat (length ls) <= lo \/ SP <= R) ->
  mem_inv bsegs m -> ACONST m ->
  evt bsegs (bcmp_postZ ra gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc SP
               (zmemcmp (map (@bv_unsigned 8) ls) (map (@bv_unsigned 8) rs)) lo m)
