(* [comment removed for export] *)
Definition verb_side (m : mem) (lo shi P n : Z) : Prop := aside m lo shi [(P, n)] [(P, n)].

Lemma verb_side_intro : forall m lo shi P n, 0 <= n ->
  ACONST m -> stack0 m lo shi -> accessible m P n -> shvis m P (P + n) -> verb_side m lo shi P n.
Proof.
  intros m lo shi P n N0 AC SK AP SV. pose proof AP as (P0 & PH & _).
  split; [exact AC|]. split; [exact SK|]. split.
  - apply Forall_cons; [exact AP| apply Forall_nil].
  - apply Forall_cons; [| apply Forall_nil]. cbn [fst snd]. split; [exact P0|]. split; [exact N0|]. split; [lia| exact SV].
Qed.

Lemma verb_side_now : forall m m1 lo shi hi P n,
  verb_side m lo shi P n -> munch [(lo, hi)]%Z m m1 -> wmono bsegs m m1 -> aceil <= lo ->
  ACONST m1 /\ stack0 m1 lo shi /\ accessible m1 P n /\ shvis m1 P (P + n).
Proof.
  intros m m1 lo shi hi P n S MU WM CEIL.
  assert (S1 : aside m1 lo shi [(P, n)] [(P, n)])
    by (eapply aside_transport; [exact S| exact MU| exact WM| apply Forall_cons; [apply awin_stack; exact CEIL| apply Forall_nil]]).
  destruct S1 as (AC & SK & FA & FS). split; [exact AC|]. split; [exact SK|].
  split; [exact (Forall_inv FA)|]. pose proof (Forall_inv FS) as (_ & _ & _ & K). exact K.
Qed.

(* [comment removed for export] *)
Definition verb_ctx (m m1 : mem) (sp s0v s1v rav : word) (j8 : list byte) (P : Z) (bs : list byte) (p' n' lo shi : Z) : Prop :=
  rw_cells bsegs m1 (bv_unsigned sp + -48) [CB 8 j8]
  /\ rw_cells bsegs m1 (bv_unsigned sp + -40) [C8 (wz p'); C8 (wz n'); C8 s1v; C8 s0v; C8 rav]
  /\ bytes_at bsegs m1 P bs
  /\ stk bsegs m1 lo (bv_unsigned sp + -48)
  /\ munch [(lo, bv_unsigned sp)]%Z m m1 /\ wmono bsegs m m1 /\ mem_inv bsegs m1
  /\ verb_side m lo shi P (Z.of_nat (length bs)).

Definition verb_pure (sp : word) (P : Z) (bs : list byte) (lo shi : Z) : Prop :=
  P + Z.of_nat (length bs) < 2^64 /\ lo + ASTRING_TO_VERB_STACK <= bv_unsigned sp /\ aceil <= lo
  /\ (bv_unsigned sp <= P \/ P + Z.of_nat (length bs) <= lo)
  /\ bv_unsigned sp mod 16 = 0 /\ bv_unsigned sp <= shi
  /\ in_app_mem P (P + Z.of_nat (length bs))
  /\ 0 < P.                                 (* [comment removed for export] *)

End HCW.

