  verb_ctx m m1 sp s0v s1v ra j8 P bs p' n' lo shi -> verb_pure sp P bs lo shi ->
  verb_of (zbytes bs) = 0 ->
  evt bsegs (string_to_verb_post ra sp gp tp s0v s1v s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc P bs lo shi m)
